    {
        uint32_t r[4];
        ldmatrix_x4(r, tile, 0, 0);
        // decode: reg = 2 bf16, low half first
        auto get = [&](uint32_t reg, int half) {
            uint16_t u = (half == 0) ? (uint16_t)(reg & 0xffff) : (uint16_t)(reg >> 16);
            bf16 b; b.x = u;
            return __bfloat162float(b);
        };
        int arow = lane / 4;
        int acol = 2 * (lane % 4);
        float expect_a0 = (float)(arow * 128 + acol + 1);
        float expect_a1 = (float)(arow * 128 + acol + 8 + 1);
        float expect_a2 = (float)((arow + 8) * 128 + acol + 1);
        float expect_a3 = (float)((arow + 8) * 128 + acol + 8 + 1);
        if (get(r[0], 0) != expect_a0 || get(r[0], 1) != expect_a0 + 1 ||
            get(r[1], 0) != expect_a1 || get(r[1], 1) != expect_a1 + 1 ||
            get(r[2], 0) != expect_a2 || get(r[2], 1) != expect_a2 + 1 ||
            get(r[3], 0) != expect_a3 || get(r[3], 1) != expect_a3 + 1) {
            local_err |= 1;
            if (lane == 0) printf("T1 x4 FAIL lane0: r0=(%g,%g) exp (%g,%g)\n",
                get(r[0],0), get(r[0],1), expect_a0, expect_a0+1);
        }
    }

    // ---- Test 2: ldmatrix.x2.trans (K-style) on rows 0-7, cols 0-15.
    // B-fragment target (B = K^T col-major, k=head, n=KV):
    // b0 = (k=2*(l%4), n=l/4) -> K[n][k] = tile[l/4][2*(l%4)]; b1 = K[n][k+8].
    {
        uint32_t r[2];
        ldmatrix_x2_trans_k(r, tile, 0, 0);
        auto get = [&](uint32_t reg, int half) {
            uint16_t u = (half == 0) ? (uint16_t)(reg & 0xffff) : (uint16_t)(reg >> 16);
            bf16 b; b.x = u;
            return __bfloat162float(b);
        };
        int kv = lane / 4;          // n = KV row
        int hd = 2 * (lane % 4);    // k = head col
        float e0 = (float)(kv * 128 + hd + 1);
        float e1 = (float)(kv * 128 + hd + 8 + 1);
        if (get(r[0], 0) != e0 || get(r[0], 1) != e0 + 1 ||
            get(r[1], 0) != e1 || get(r[1], 1) != e1 + 1) {
            local_err |= 2;
            if (lane < 4) printf("T2 x2transK FAIL lane%d: r0=(%g,%g) exp(%g,%g) r1=(%g,%g) exp(%g,%g)\n",
                lane, get(r[0],0), get(r[0],1), e0, e0+1, get(r[1],0), get(r[1],1), e1, e1+1);
        }
    }

    // ---- Test 3: ldmatrix.x2.trans (V-style) on rows 0-15, cols 0-7.
    // B = V col-major (k=KV, n=head): b0 = V[2*(l%4)][l/4], b1 = V[2*(l%4)+8][l/4].
    {
        uint32_t r[2];
        ldmatrix_x2_trans_v(r, tile, 0, 0);
        auto get = [&](uint32_t reg, int half) {
            uint16_t u = (half == 0) ? (uint16_t)(reg & 0xffff) : (uint16_t)(reg >> 16);
            bf16 b; b.x = u;
            return __bfloat162float(b);
        };
        int kv = 2 * (lane % 4);
        int hd = lane / 4;
        float e0 = (float)(kv * 128 + hd + 1);
        float e1 = (float)((kv + 8) * 128 + hd + 1);
        if (get(r[0], 0) != e0 || get(r[0], 1) != e0 + 128 ||
            get(r[1], 0) != e1 || get(r[1], 1) != e1 + 128) {
            local_err |= 4;
            if (lane < 4) printf("T3 x2transV FAIL lane%d: r0=(%g,%g) exp(%g,%g) r1=(%g,%g) exp(%g,%g)\n",
                lane, get(r[0],0), get(r[0],1), e0, e0+128, get(r[1],0), get(r[1],1), e1, e1+128);
        }
    }

    // ---- Test 4: end-to-end mma: S = Q*K^T with Q = identity-ish (row value), K tile.
    // Verify against CPU-computed reference for one mma.
    {
        // Q tile: 16x16 at rows 0-15, cols 0-15 -> values = row*128+col+1
        // K tile: rows 0-7 (KV), cols 0-15 (head) -> same values
        // S[m][n] = sum_k Q[m][k]*K[n][k] = sum_k (m*128+k+1)*(n*128+k+1), k=0..15
        uint32_t q[4], kf[2];
        ldmatrix_x4(q, tile, 0, 0);
        ldmatrix_x2_trans_k(kf, tile, 0, 0);
        float acc[4] = {0, 0, 0, 0};
        mma_m16n8k16_bf16(acc, q, kf, acc);
        int row = lane / 4, col = 2 * (lane % 4);
        for (int i = 0; i < 2; i++) {
            int m = row + (i < 2 ? 0 : 8);
            int n = col + (i % 2);
            // acc[i] = S[m][n], acc[i+2] = S[m+8][n]
            float ref = 0.f;
            for (int k = 0; k < 16; k++) {
                float qv = (float)(m * 128 + k + 1);
                float kv_ = (float)(n * 128 + k + 1);
                ref += qv * kv_;
            }
            int idx = (i < 2) ? i : i;
            if (fabsf(acc[idx] - ref) > 1.f) {
                local_err |= 8;
                if (lane < 4)
                    printf("T4 mma FAIL lane%d acc[%d]=%g ref=%g\n", lane, idx, acc[idx], ref);
            }
        }
    }

    if (local_err) {
        atomicAdd(err, local_err);
        if (lane == 0) printf("probe kernel: err bits = %d\n", local_err);
    }
}

int main() {
    int* err_d;
    cudaMalloc(&err_d, sizeof(int));
    cudaMemset(err_d, 0, sizeof(int));
    probe_kernel<<<1, 32>>>(err_d);
    cudaError_t e = cudaDeviceSynchronize();
    int err = 0;
    cudaMemcpy(&err, err_d, sizeof(int), cudaMemcpyDeviceToHost);
    printf("probe: cudaError=%s err=%d\n", cudaGetErrorString(e), err);
    return err ? 1 : 0;
}

