        float e2 = bf((float)((arow + 8) * 16 + acol + 1));
        float e3 = bf((float)((arow + 8) * 16 + acol + 8 + 1));
        if (get(q[0],0)!=e0 || get(q[0],1)!=bf(e0+1) || get(q[1],0)!=e1 || get(q[1],1)!=bf(e1+1) ||
            get(q[2],0)!=e2 || get(q[2],1)!=bf(e2+1) || get(q[3],0)!=e3 || get(q[3],1)!=bf(e3+1)) {
            local_err |= 1;
            if (lane < 2) printf("T1 x4 FAIL lane%d: r=(%g,%g)(%g,%g)(%g,%g)(%g,%g) exp (%g,%g)(%g,%g)(%g,%g)(%g,%g)\n",
                lane, get(q[0],0),get(q[0],1),get(q[1],0),get(q[1],1),get(q[2],0),get(q[2],1),get(q[3],0),get(q[3],1),
                e0,bf(e0+1),e1,bf(e1+1),e2,bf(e2+1),e3,bf(e3+1));
        }
    }

    // ---- Test 2: QK mma: S[m][n] = sum_k Q[m][k]*K[n][k] via B = K^T (non-trans x2)
    {
        uint32_t q[4], kf[2];
        ldmatrix_x4(q, sQ, 0, 0);
        ldmatrix_x2_k(kf, sK, 0, 0);
        float acc[4] = {0,0,0,0};
        mma_m16n8k16_bf16(acc, q, kf, acc);
        int row = lane / 4, col = 2 * (lane % 4);
        auto bf = [](float v) { return __bfloat162float(__float2bfloat16(v)); };
        for (int i = 0; i < 4; i++) {
            int m = (i < 2) ? row : row + 8;
            int n = col + (i % 2);
