        __shared__ bf16 sS[16][16];
        for (int i = threadIdx.x; i < 16 * 16; i += blockDim.x)
            sS[i / 16][i % 16] = __float2bfloat16((float)(i + 1));
        __syncthreads();
        uint32_t p[4], vf[2];
        ldmatrix_x4(p, sS, 0, 0);          // A = S fragment
        ldmatrix_x2_trans_v(vf, sV, 0, 0); // B = V
        float acc[4] = {0,0,0,0};
        mma_m16n8k16_bf16(acc, p, vf, acc);
        int row = lane / 4, col = 2 * (lane % 4);
        auto bf = [](float v) { return __bfloat162float(__float2bfloat16(v)); };
        for (int i = 0; i < 4; i++) {
            int m = (i < 2) ? row : row + 8;
            int n = col + (i % 2);
            float ref = 0.f;
            for (int k = 0; k < 16; k++)
                ref += bf((float)(m * 16 + k + 1)) * bf((float)(k * 8 + n + 1));
            if (fabsf(acc[i] - ref) > 0.01f * ref) {
                local_err |= 4;
                if (lane < 2) printf("T3 PV FAIL lane%d acc[%d]=%g ref=%g (m=%d n=%d)\n", lane, i, acc[i], ref, m, n);
            }
        }
    }

    // ---- Test 4: SWIZZLED addressing roundtrip: write via swizzled addr, read via swizzled addr
    {
        __shared__ bf16 sT[8][128];
        for (int i = threadIdx.x; i < 8 * 128; i += blockDim.x) {
            int r = i / 128, c = i % 128;
            int sw = (c >> 3) ^ (r & 7);
            ((bf16*)sT)[r * 128 + sw * 8 + (c & 7)] = __float2bfloat16((float)(i + 1));
        }
        __syncthreads();
        // read back via swizzled x4 on rows 0-7, cols 0-15 -> A fragment rows 0-7 only
        uint32_t q[4];
        int lane2 = lane;
        int trow = 0 + (lane2 & 7);
        int tcol8 = 0 + ((lane2 >> 3) & 1);
        uint32_t addr = smem_addr16(sT, trow, tcol8); // NOTE: linear addr helper (no swizzle) -> but we need swizzled!
        // use swizzled addressing manually:
        int sw = tcol8 ^ (trow & 7);
        const char* p = (const char*)sT + trow * 256 + sw * 16;
        uint32_t addr2 = (uint32_t)__cvta_generic_to_shared(p);
        asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];\n"
                     : "=r"(q[0]), "=r"(q[1]) : "r"(addr2));
        auto bf = [](float v) { return __bfloat162float(__float2bfloat16(v)); };
        int row = lane2 / 4, col = 2 * (lane2 % 4);
        float e0 = bf((float)(row * 128 + col + 1));
        float e1 = bf((float)(row * 128 + col + 8 + 1));
        if (get(q[0],0)!=e0 || get(q[0],1)!=bf(e0+1) || get(q[1],0)!=e1 || get(q[1],1)!=bf(e1+1)) {
            local_err |= 8;
            if (lane2 < 2) printf("T4 SWZ FAIL lane%d: (%g,%g)(%g,%g) exp (%g,%g)(%g,%g)\n",
                lane2, get(q[0],0),get(q[0],1),get(q[1],0),get(q[1],1), e0,bf(e0+1),e1,bf(e1+1));
        }
    }

    if (local_err) {
        atomicAdd(err, local_err);
        if (lane == 0) printf("probe2: err bits = %d\n", local_err);
    }
}

