        int arow = lane / 4, acol = 2 * (lane % 4);
        float e0 = bf((float)(arow * 128 + acol + 1));
        float e1 = bf((float)(arow * 128 + acol + 8 + 1));
        float e2 = bf((float)((arow + 8) * 128 + acol + 1));
        float e3 = bf((float)((arow + 8) * 128 + acol + 8 + 1));
        if (getf(q[0],0)!=e0 || getf(q[0],1)!=bf(e0+1) || getf(q[1],0)!=e1 || getf(q[1],1)!=bf(e1+1) ||
            getf(q[2],0)!=e2 || getf(q[2],1)!=bf(e2+1) || getf(q[3],0)!=e3 || getf(q[3],1)!=bf(e3+1)) {
            local_err |= 1;
            if (lane < 2) printf("T1 x4 FAIL lane%d: (%g,%g)(%g,%g)(%g,%g)(%g,%g) exp (%g,%g)(%g,%g)(%g,%g)(%g,%g)\n",
                lane, getf(q[0],0),getf(q[0],1),getf(q[1],0),getf(q[1],1),getf(q[2],0),getf(q[2],1),getf(q[3],0),getf(q[3],1),
                e0,bf(e0+1),e1,bf(e1+1),e2,bf(e2+1),e3,bf(e3+1));
        }
    }

    // ---- Test 2: QK mma: S[m][n] = sum_k Q[m][k]*K[n][k]
    {
        uint32_t q[4], kf[2];
        ldmatrix_x4(q, sQ, 0, 0);
        ldmatrix_x2_k(kf, sK, 0, 0);
        float acc[4] = {0,0,0,0};
        mma_m16n8k16_bf16(acc, q, kf, acc);
        int row = lane / 4, col = 2 * (lane % 4);
        for (int i = 0; i < 4; i++) {
            int m = (i < 2) ? row : row + 8;
            int n = col + (i % 2);
            float ref = 0.f;
            for (int k = 0; k < 16; k++)
                ref += bf((float)(m * 128 + k + 1)) * bf((float)(n * 128 + k + 1));
            if (fabsf(acc[i] - ref) > 0.01f * ref) {
                local_err |= 2;
                if (lane < 2) printf("T2 QK FAIL lane%d acc[%d]=%g ref=%g (m=%d n=%d)\n", lane, i, acc[i], ref, m, n);
            }
        }
    }

    // ---- Test 3: PV mma with acc-as-A: O[m][n] = sum_k S[m][k]*V[k][n], S from sQ
    {
        uint32_t p[4], vf[2];
        ldmatrix_x4(p, sQ, 0, 0);          // A = S fragment (16x16)
        ldmatrix_x2_trans_v(vf, sV, 0, 0); // B = V (16 KV rows x 8 head)
        float acc[4] = {0,0,0,0};
        mma_m16n8k16_bf16(acc, p, vf, acc);
        int row = lane / 4, col = 2 * (lane % 4);
        for (int i = 0; i < 4; i++) {
            int m = (i < 2) ? row : row + 8;
            int n = col + (i % 2);
            float ref = 0.f;
            for (int k = 0; k < 16; k++)
                ref += bf((float)(m * 128 + k + 1)) * bf((float)(k * 128 + n + 1));
            if (fabsf(acc[i] - ref) > 0.01f * ref) {
                local_err |= 4;
                if (lane < 2) printf("T3 PV FAIL lane%d acc[%d]=%g ref=%g (m=%d n=%d)\n", lane, i, acc[i], ref, m, n);
            }
        }
    }

    // ---- Test 4: SWIZZLED addressing roundtrip with x2 (B=K^T style, 8 rows x 16 cols)
    {
        __shared__ bf16 sT[8][128];
        for (int i = threadIdx.x; i < 8 * 128; i += blockDim.x) {
            int r = i / 128, c = i % 128;
            int sw = (c >> 3) ^ (r & 7);
            sT[r][sw * 8 + (c & 7)] = __float2bfloat16((float)(i + 1));
        }
        __syncthreads();
        uint32_t kf[2];
        int trow = 0 + (lane & 7);
        int tcol8 = 0 + (lane >> 3);
        if (tcol8 > 15) tcol8 = 15;
        int sw = tcol8 ^ (trow & 7);
        uint32_t addr = (uint32_t)__cvta_generic_to_shared((const char*)sT + trow * 256 + sw * 16);
        asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];\n"
                     : "=r"(kf[0]), "=r"(kf[1]) : "r"(addr));
        int row = lane / 4, col = 2 * (lane % 4);
        float e0 = bf((float)(row * 128 + col + 1));
        float e1 = bf((float)(row * 128 + col + 8 + 1));
        if (getf(kf[0],0)!=e0 || getf(kf[0],1)!=bf(e0+1) || getf(kf[1],0)!=e1 || getf(kf[1],1)!=bf(e1+1)) {
            local_err |= 8;
            if (lane < 2) printf("T4 SWZ FAIL lane%d: (%g,%g)(%g,%g) exp (%g,%g)(%g,%g)\n",
                lane, getf(kf[0],0),getf(kf[0],1),getf(kf[1],0),getf(kf[1],1), e0,bf(e0+1),e1,bf(e1+1));
        }
    }

    // ---- Test 5: x4 swizzled (A fragment, 16x16 at rows 0-15, cols 0-15)
    {
        __shared__ bf16 sQ2[16][128];
        for (int i = threadIdx.x; i < 16 * 128; i += blockDim.x) {
            int r = i / 128, c = i % 128;
            int sw = (c >> 3) ^ (r & 7);
            sQ2[r][sw * 8 + (c & 7)] = __float2bfloat16((float)(i + 1));
        }
        __syncthreads();
        uint32_t q[4];
        int trow = 0 + (lane & 7) + ((lane >> 4) << 3);
        int tcol8 = 0 + ((lane >> 3) & 1);
        int sw = tcol8 ^ (trow & 7);
        uint32_t addr = (uint32_t)__cvta_generic_to_shared((const char*)sQ2 + trow * 256 + sw * 16);
        asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                     : "=r"(q[0]), "=r"(q[1]), "=r"(q[2]), "=r"(q[3]) : "r"(addr));
        int arow = lane / 4, acol = 2 * (lane % 4);
        float e0 = bf((float)(arow * 128 + acol + 1));
        float e1 = bf((float)(arow * 128 + acol + 8 + 1));
        float e2 = bf((float)((arow + 8) * 128 + acol + 1));
        float e3 = bf((float)((arow + 8) * 128 + acol + 8 + 1));
        if (getf(q[0],0)!=e0 || getf(q[0],1)!=bf(e0+1) || getf(q[1],0)!=e1 || getf(q[1],1)!=bf(e1+1) ||
            getf(q[2],0)!=e2 || getf(q[2],1)!=bf(e2+1) || getf(q[3],0)!=e3 || getf(q[3],1)!=bf(e3+1)) {
            local_err |= 16;
            if (lane < 2) printf("T5 SWZx4 FAIL lane%d: (%g,%g)(%g,%g)(%g,%g)(%g,%g) exp (%g,%g)(%g,%g)(%g,%g)(%g,%g)\n",
                lane, getf(q[0],0),getf(q[0],1),getf(q[1],0),getf(q[1],1),getf(q[2],0),getf(q[2],1),getf(q[3],0),getf(q[3],1),
                e0,bf(e0+1),e1,bf(e1+1),e2,bf(e2+1),e3,bf(e3+1));
        }
    }

    if (local_err) {
        atomicAdd(err, local_err);
        if (lane == 0) printf("probe3: err bits = %d\n", local_err);
    }
}

int main() {
    int* err_d;
    cudaMalloc(&err_d, sizeof(int));
    cudaMemset(err_d, 0, sizeof(int));
    probe_kernel<<<1, 32>>>(err_d);
    cudaError_t e = cudaDeviceSynchronize();
    int err = 0;
    cudaMemcpy(&err, err_d, sizeof(int), cudaMemcpyDeviceToHost);
    printf("probe3: cudaError=%s err=%d\n", cudaGetErrorString(e), err);
    return err ? 1 : 0;
}

